{"source":{"files":[{"name":"firestore.rules","content":"rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /hh0000/{room} {
      allow read: if request.auth != null || resource.data.visibility == 'public';
    }
    match /hh0001/{room} {
      allow read: if resource.data.get('visibility', 'private') == 'public' || request.auth == null;
    }
    match /hh0002/{room} {
      allow read: if resource.data.tags.size() < 5 && resource.data.tags.hasAll(['a']);
    }
    match /hh0003/{room} {
      allow read: if resource.data.s.size() > 2 && resource.data.s.size() <= 30;
    }
    match /hh0004/{room} {
      allow read: if resource.data.keys().hasOnly(['n', 'f', 'one_f', 's', 'b', 'nul', 'arr', 'tags', 'm', 'ts', 'geo', 'ref', 'by', 'big']);
    }
    match /hh0005/{room} {
      allow read: if resource.data.ts < request.time - duration.value(1, 'd');
    }
    match /hh0006/{room} {
      allow read: if request.time < timestamp.date(2000, 1, 1);
    }
    match /hh0007/{room} {
      allow read: if resource.data.m.size() == 2 && 'x' in resource.data.m;
    }
    match /hh0008/{room} {
      allow read: if resource.data.n is int && resource.data.n >= 0 && resource.data.n < 10;
    }
    match /hh0009/{room} {
      allow read: if resource.data.f > 1 && resource.data.f < 2;
    }
    match /hh0010/{room} {
      allow read: if resource.data.f * 2 == 3;
    }
    match /hh0011/{room} {
      allow read: if resource.data.n / 2 == 0;
    }
    match /hh0012/{room} {
      allow read: if resource.data.n % 2 == 1;
    }
    match /hh0013/{room} {
      allow read: if resource.data.s in ['abc', 'def'];
    }
    match /hh0014/{room} {
      allow read: if resource.data.n in [1, 2, 3];
    }
    match /hh0015/{room} {
      allow read: if resource.data.tags[0] == 'a';
    }
    match /hh0016/{room} {
      allow read: if resource.data.tags[-1] == 'b';
    }
    match /hh0017/{room} {
      allow read: if resource.data.arr[3] == 4;
    }
    match /hh0018/{room} {
      allow read: if resource.data.s.matches('^a.*');
    }
    match /hh0019/{room} {
      allow read: if resource.data.s.matches('A.*');
    }
    match /hh0020/{room} {
      allow read: if resource.data.s.lower().matches('[a-z]+');
    }
    match /hh0021/{room} {
      allow read: if resource.data.s.split('b').size() == 2;
    }
    match /hh0022/{room} {
      allow read: if resource.data.s.replace('b', '') == 'ac';
    }
    match /hh0023/{room} {
      allow read: if resource.data.m.keys().size() == 2 && resource.data.m.values().size() == 2;
    }
    match /hh0024/{room} {
      allow read: if resource.data.m.diff({}).addedKeys().size() == 2;
    }
    match /hh0025/{room} {
      allow read: if resource.data.m.diff(resource.data.m).affectedKeys().size() == 0;
    }
    match /hh0026/{room} {
      allow read: if resource.data.arr.toSet().hasAny([3]);
    }
    match /hh0027/{room} {
      allow read: if resource.data.arr.concat(resource.data.tags).size() == 5;
    }
    match /hh0028/{room} {
      allow read: if resource.data.big > 9000000000000000000;
    }
    match /hh0029/{room} {
      allow read: if resource.data.big - 1 < resource.data.big;
    }
    match /hh0030/{room} {
      allow read: if -resource.data.big - 2 < 0;
    }
    match /hh0031/{room} {
      allow read: if resource.data.geo.latitude() < resource.data.geo.longitude();
    }
    match /hh0032/{room} {
      allow read: if string(resource.data.n) + string(resource.data.f) == '11.5';
    }
    match /hh0033/{room} {
      allow read: if int(resource.data.f) == 1 && float(resource.data.n) == 1.0;
    }
    match /hh0034/{room} {
      allow read: if math.abs(resource.data.f - 2) == 0.5;
    }
    match /hh0035/{room} {
      allow read: if resource.data.ts.toMillis() > 0 && resource.data.ts.year() >= 2020;
    }
    match /hh0036/{room} {
      allow read: if duration.value(resource.data.n, 'd') == duration.value(24, 'h');
    }
    match /hh0037/{room} {
      allow read: if resource.__name__[3] == 'rooms' && resource.__name__[4] == room;
    }
    match /hh0038/{room} {
      allow read: if request.path[4] == resource.id;
    }
    match /hh0039/{room} {
      allow read: if resource.data.nul == null && !(resource.data.b == false);
    }
    match /hh0040/{room} {
      allow read: if (resource.data.missing == 1) == false;
    }
    match /hh0041/{room} {
      allow read: if resource.data.get('m', {}).get('x', 0) == 1;
    }
    match /hh0042/{room} {
      allow read: if resource.data.tags.join('-').size() == 3;
    }
    match /hh0043/{room} {
      allow read: if 'a' in resource.data.tags.toSet();
    }
    match /hh0044/{room} {
      allow read: if resource.data.tags.toSet().union(['c'].toSet()).size() == 3;
    }
    match /hh0045/{room} {
      allow read: if [1, 2, 3].hasOnly(resource.data.arr);
    }
    match /hh0046/{room} {
      allow read: if resource.data.s + resource.data.s == 'abcabc';
    }
    match /hh0047/{room} {
      allow read: if resource.data.f + resource.data.n == 2.5;
    }
    match /hh0048/{room} {
      allow read: if resource.data.n + 0.5 == 1.5;
    }
    match /hh0049/{room} {
      allow read: if resource.data.f % 1 == 0.5;
    }
    match /hh0050/{room} {
      allow read: if resource.data.one_f == resource.data.n;
    }
    match /hh0051/{room} {
      allow read: if [resource.data.one_f] == [resource.data.n];
    }
    match /hh0052/{room} {
      allow read: if {'a': resource.data.n} == {'a': 1};
    }
    match /hh0053/{room} {
      allow read: if resource.data.m.x is int && resource.data.m.y is string;
    }
    match /hh0054/{room} {
      allow read: if resource.data is map;
    }
    match /hh0055/{room} {
      allow read: if request.auth is map;
    }
    match /hh0056/{room} {
      allow read: if request.time is timestamp;
    }
    match /hh0057/{room} {
      allow read: if request.time - resource.data.ts > duration.value(1, 'd');
    }
    match /hh0058/{room} {
      allow read: if resource.data.s[0] == 'a' && resource.data.s[1:3] == 'bc';
    }
    match /hh0059/{room} {
      allow read: if resource.data.arr[0:2].size() == 2;
    }
  }
}
